// Strategy interface: which deliveries are legal, and how many extras they earn.
interface ScoringRuleStrategy {
    boolean isLegalDelivery(DeliveryType type); // counts toward the six balls of an over
    int extraRuns(DeliveryType type);            // extra runs added beyond what was scored off the bat
}

// The standard rules: normal deliveries are legal and add no extras;
// wides and no-balls are illegal and each add exactly one extra run.
class StandardScoringRuleStrategy implements ScoringRuleStrategy {
    @Override
    public boolean isLegalDelivery(DeliveryType type) {
        return type == DeliveryType.NORMAL; // only a normal delivery counts toward the over
    }

    @Override
    public int extraRuns(DeliveryType type) {
        if (type == DeliveryType.WIDE || type == DeliveryType.NO_BALL) return 1; // one extra run
        return 0; // a normal delivery adds no extra beyond what was scored
    }
}

// The derived, computed state of an innings at a point in time.
class MatchState {
    private final int totalRuns;           // runs scored off the bat plus all extras
    private final int wickets;              // wickets fallen so far
    private final int oversCompleted;        // full overs of six legal balls completed
    private final int ballsInCurrentOver;     // legal balls bowled in the over still in progress
    private final int strikeBatsmanIndex;      // which of the two current batsmen is on strike, 0 or 1

    public MatchState(int totalRuns, int wickets, int oversCompleted, int ballsInCurrentOver, int strikeBatsmanIndex) {
        this.totalRuns = totalRuns;                 // store total
        this.wickets = wickets;                       // store wickets
        this.oversCompleted = oversCompleted;           // store overs
        this.ballsInCurrentOver = ballsInCurrentOver;     // store balls in progress
        this.strikeBatsmanIndex = strikeBatsmanIndex;       // store strike index
    }

    public int getTotalRuns() { return totalRuns; }                 // total getter
    public int getWickets() { return wickets; }                       // wickets getter
    public int getOversCompleted() { return oversCompleted; }           // overs getter
    public int getBallsInCurrentOver() { return ballsInCurrentOver; }     // balls-in-over getter
    public int getStrikeBatsmanIndex() { return strikeBatsmanIndex; }       // strike getter
}

// Owns the append-only event log of deliveries for one batting turn.
class Innings {
    private final String inningsId;                                          // unique id
    private final String battingTeam;                                         // team currently batting
    private final String bowlingTeam;                                          // team currently bowling
    private final java.util.List<Delivery> deliveries = new java.util.ArrayList<>(); // append-only event log
    private boolean complete;                                                    // whether the overs limit has been reached

    public Innings(String inningsId, String battingTeam, String bowlingTeam) {
        this.inningsId = inningsId;   // store id
        this.battingTeam = battingTeam; // store batting team
        this.bowlingTeam = bowlingTeam;  // store bowling team
        this.complete = false;            // starts not complete
    }

    public String getInningsId() { return inningsId; }               // id getter
    public java.util.List<Delivery> getDeliveries() { return deliveries; } // log getter
    public void appendDelivery(Delivery delivery) { deliveries.add(delivery); } // append to the log
    public boolean isComplete() { return complete; }                    // complete getter
    public void markComplete() { this.complete = true; }                 // mark complete
}

