// Observer interface: reacts to key scoring events.
interface MatchObserver {
    void onDeliveryRecorded(Delivery delivery);   // a new delivery was appended
    void onWicketFallen(String inningsId);          // a wicket just fell
    void onOverCompleted(String inningsId);           // six legal balls just completed
    void onInningsCompleted(String inningsId);          // the overs limit was just reached
}

// Simple observer that prints events to the console.
class ConsoleMatchObserver implements MatchObserver {
    @Override
    public void onDeliveryRecorded(Delivery delivery) {
        System.out.println("Delivery " + delivery.getDeliveryId() + " recorded: " + delivery.getRunsScored() + " runs, " + delivery.getDeliveryType());
    }

    @Override
    public void onWicketFallen(String inningsId) {
        System.out.println("Wicket fallen in innings " + inningsId);
    }

    @Override
    public void onOverCompleted(String inningsId) {
        System.out.println("Over completed in innings " + inningsId);
    }

    @Override
    public void onInningsCompleted(String inningsId) {
        System.out.println("Innings " + inningsId + " completed, overs limit reached");
    }
}

// Custom exceptions for the realistic failure modes.
class InningsCompleteException extends RuntimeException {
    public InningsCompleteException(String msg) { super(msg); }
}
class InvalidDeliveryException extends RuntimeException {
    public InvalidDeliveryException(String msg) { super(msg); }
}
class InvalidInningsException extends RuntimeException {
    public InvalidInningsException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class MatchService {
    private final java.util.Map<String, Innings> innings = new java.util.HashMap<>(); // inningsId -> Innings
    private final ScoringRuleStrategy scoringRuleStrategy; // pluggable rules
    private final java.util.List<MatchObserver> observers = new java.util.ArrayList<>(); // listeners
    private final int oversLimit; // legal balls limit divided by six for this innings

    public MatchService(ScoringRuleStrategy scoringRuleStrategy, int oversLimit) {
        this.scoringRuleStrategy = scoringRuleStrategy; // store chosen rules
        this.oversLimit = oversLimit;                     // store overs limit
    }

    public void addInnings(Innings inn) { innings.put(inn.getInningsId(), inn); } // register an innings
    public void addObserver(MatchObserver observer) { observers.add(observer); }    // register a listener

    // Replays the entire delivery log to derive the current state, from scratch every time.
    public MatchState getCurrentState(String inningsId) {
        Innings inn = innings.get(inningsId);           // look up innings
        if (inn == null) throw new InvalidInningsException("Unknown innings: " + inningsId);
        int totalRuns = 0;                                 // running total across the whole replay
        int wickets = 0;                                     // running wicket count
        int legalBalls = 0;                                    // legal balls bowled so far
        int strikeIndex = 0;                                     // which batsman is on strike, 0 or 1
        for (Delivery d : inn.getDeliveries()) {                  // replay every event in order
            totalRuns += d.getRunsScored();                          // add runs scored off the bat
            totalRuns += scoringRuleStrategy.extraRuns(d.getDeliveryType()); // add any extras
            if (d.isWicket()) wickets++;                                // count a wicket
            boolean legal = scoringRuleStrategy.isLegalDelivery(d.getDeliveryType()); // legal or an extra
            if (legal) {                                                    // only legal balls affect over progress
                legalBalls++;                                                  // one more legal ball bowled
                if (d.getRunsScored() % 2 == 1) strikeIndex = 1-strikeIndex;   // odd runs rotate strike
                if (legalBalls % 6 == 0) strikeIndex = 1-strikeIndex;            // end of over also rotates strike
            }
        }
        int oversCompleted = legalBalls / 6;               // full overs completed
        int ballsInCurrentOver = legalBalls % 6;             // legal balls into the current, unfinished over
        return new MatchState(totalRuns, wickets, oversCompleted, ballsInCurrentOver, strikeIndex); // derived result
    }

    // Appends a new delivery, enforcing the overs limit, and returns the freshly derived state.
    public synchronized MatchState recordDelivery(String inningsId, int runsScored, DeliveryType type, boolean isWicket, DeliveryFactory factory) {
        Innings inn = innings.get(inningsId);                  // look up innings
        if (inn == null) throw new InvalidInningsException("Unknown innings: " + inningsId);
        if (inn.isComplete()) {                                    // overs limit already reached
            throw new InningsCompleteException("Innings " + inningsId + " is already complete");
        }
        if (runsScored < 0) throw new InvalidDeliveryException("Runs scored cannot be negative"); // guard bad input
        Delivery delivery = factory.createDelivery(runsScored, type, isWicket); // build the event
        inn.appendDelivery(delivery);                                             // append it to the log
        for (MatchObserver obs : observers) obs.onDeliveryRecorded(delivery);       // notify
        if (isWicket) { for (MatchObserver obs : observers) obs.onWicketFallen(inningsId); } // notify wicket
        MatchState state = getCurrentState(inningsId);                              // replay to derive fresh state
        if (scoringRuleStrategy.isLegalDelivery(type) && state.getBallsInCurrentOver() == 0 && state.getOversCompleted() > 0) {
            for (MatchObserver obs : observers) obs.onOverCompleted(inningsId);        // notify over completion
        }
        if (state.getOversCompleted() >= oversLimit) {                                // overs limit just reached
            inn.markComplete();                                                          // mark innings complete
            for (MatchObserver obs : observers) obs.onInningsCompleted(inningsId);          // notify
        }
        return state; // hand back the freshly derived state
    }
}

