    map<string, Innings> innings;                      // inningsId -> Innings
    shared_ptr<ScoringRuleStrategy> scoringRuleStrategy;  // pluggable rules
    vector<shared_ptr<MatchObserver>> observers;           // listeners
    int oversLimit;                                          // legal balls limit divided by six for this innings

