        : scoringRuleStrategy(strategy), oversLimit(limit) {}

    void addInnings(Innings inn) { innings.insert({inn.inningsId, inn}); } // register an innings
    void addObserver(shared_ptr<MatchObserver> observer) { observers.push_back(observer); } // register a listener

    MatchState getCurrentState(string inningsId) {
        auto it = innings.find(inningsId);            // look up innings
        if (it == innings.end()) throw InvalidInningsException("Unknown innings: " + inningsId);
        Innings& inn = it->second;
        int totalRuns = 0;                               // running total across the whole replay
        int wickets = 0;                                    // running wicket count
        int legalBalls = 0;                                    // legal balls bowled so far
        int strikeIndex = 0;                                     // which batsman is on strike, 0 or 1
        for (auto& d : inn.deliveries) {                          // replay every event in order
            totalRuns += d.runsScored;                                // add runs scored off the bat
            totalRuns += scoringRuleStrategy->extraRuns(d.deliveryType); // add any extras
            if (d.isWicket) wickets++;                                   // count a wicket
            bool legal = scoringRuleStrategy->isLegalDelivery(d.deliveryType); // legal or an extra
            if (legal) {                                                   // only legal balls affect over progress
                legalBalls++;                                                // one more legal ball bowled
                if (d.runsScored % 2 == 1) strikeIndex = 1-strikeIndex;         // odd runs rotate strike
                if (legalBalls % 6 == 0) strikeIndex = 1-strikeIndex;             // end of over also rotates strike
            }
        }
        int oversCompleted = legalBalls / 6;               // full overs completed
        int ballsInCurrentOver = legalBalls % 6;             // legal balls into the current, unfinished over
        return MatchState(totalRuns, wickets, oversCompleted, ballsInCurrentOver, strikeIndex); // derived result
    }

    MatchState recordDelivery(string inningsId, int runsScored, DeliveryType type, bool isWicket, DeliveryFactory& factory) {
        auto it = innings.find(inningsId);                  // look up innings
        if (it == innings.end()) throw InvalidInningsException("Unknown innings: " + inningsId);
        Innings& inn = it->second;
        if (inn.complete) {                                    // overs limit already reached
            throw InningsCompleteException("Innings " + inningsId + " is already complete");
        }
        if (runsScored < 0) throw InvalidDeliveryException("Runs scored cannot be negative"); // guard bad input
        Delivery delivery = factory.createDelivery(runsScored, type, isWicket); // build the event
        inn.appendDelivery(delivery);                                             // append it to the log
        for (auto& obs : observers) obs->onDeliveryRecorded(delivery);              // notify
        if (isWicket) { for (auto& obs : observers) obs->onWicketFallen(inningsId); } // notify wicket
        MatchState state = getCurrentState(inningsId);                                // replay to derive fresh state
        if (scoringRuleStrategy->isLegalDelivery(type) && state.ballsInCurrentOver == 0 && state.oversCompleted > 0) {
            for (auto& obs : observers) obs->onOverCompleted(inningsId);                // notify over completion
