        if (state.oversCompleted >= oversLimit) {                                       // overs limit just reached
            inn.markComplete();                                                           // mark innings complete
            for (auto& obs : observers) obs->onInningsCompleted(inningsId);                 // notify
        }
        return state; // hand back the freshly derived state
    }
};

