        Innings inn = innings.get(inningsId);
        if (inn == null) throw new InvalidInningsException("Unknown innings: " + inningsId);
        int totalRuns = 0;
        int wickets = 0;
        int legalBalls = 0;
        int strikeIndex = 0;
        for (Delivery d : inn.getDeliveries()) {
            totalRuns += d.getRunsScored();
            totalRuns += scoringRuleStrategy.extraRuns(d.getDeliveryType());
            if (d.isWicket()) wickets++;
            boolean legal = scoringRuleStrategy.isLegalDelivery(d.getDeliveryType());
            if (legal) {
                legalBalls++;
                if (d.getRunsScored() % 2 == 1) strikeIndex = 1-strikeIndex;
                if (legalBalls % 6 == 0) strikeIndex = 1-strikeIndex;
            }
        }
        int oversCompleted = legalBalls / 6;
        int ballsInCurrentOver = legalBalls % 6;
        return new MatchState(totalRuns, wickets, oversCompleted, ballsInCurrentOver, strikeIndex);
    }

    public synchronized MatchState recordDelivery(String inningsId, int runsScored, DeliveryType type, boolean isWicket, DeliveryFactory factory) {
        Innings inn = innings.get(inningsId);
        if (inn == null) throw new InvalidInningsException("Unknown innings: " + inningsId);
        if (inn.isComplete()) {
            throw new InningsCompleteException("Innings " + inningsId + " is already complete");
        }
        if (runsScored < 0) throw new InvalidDeliveryException("Runs scored cannot be negative");
        Delivery delivery = factory.createDelivery(runsScored, type, isWicket);
        inn.appendDelivery(delivery);
        for (MatchObserver obs : observers) obs.onDeliveryRecorded(delivery);
        if (isWicket) { for (MatchObserver obs : observers) obs.onWicketFallen(inningsId); }
        MatchState state = getCurrentState(inningsId);
        if (scoringRuleStrategy.isLegalDelivery(type) && state.getBallsInCurrentOver() == 0 && state.getOversCompleted() > 0) {
            for (MatchObserver obs : observers) obs.onOverCompleted(inningsId);
        }
        if (state.getOversCompleted() >= oversLimit) {
            inn.markComplete();
            for (MatchObserver obs : observers) obs.onInningsCompleted(inningsId);
        }
        return state;
    }
}

